import numpy as np

def perceptron(X, y, epochs=20, eta=1.0):
    w, b = np.zeros(X.shape[1]), 0.0
    for _ in range(epochs):
        errors = 0
        for xi, yi in zip(X, y):
            pred = 1 if w @ xi + b >= 0 else 0
            update = eta * (yi - pred)              # nonzero only if misclassified
            w += update * xi; b += update
            errors += int(update != 0)
        if errors == 0: break                       # converged (separable)
    return w, b, errors

X = np.array([[0,0],[0,1],[1,0],[1,1]], float)
for name, y in [('AND',[0,0,0,1]), ('OR',[0,1,1,1]), ('XOR',[0,1,1,0])]:
    w, b, err = perceptron(X, np.array(y))
    print(f'{name}: final errors = {err}  ({"separable" if err==0 else "NEVER converges"})')
